// Good example: parallel data fetching for dashboard APIs
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then(r => r.json()),
      fetch('/api/notifications').then(r => r.json()),
      fetch('/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    // Return mock data for build time
    return {
      analytics: { totalUsers: 1234, pageViews: 5678, revenue: 9876 },
      notifications: [
        { id: 1, message: 'Welcome to the dashboard', read: false },
        { id: 2, message: 'System update scheduled', read: true }
      ],
      settings: { theme: 'light', notificationsEnabled: true }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="dashboard">
      <h2>Dashboard Content</h2>

      <div className="stats-grid">
        <div className="stat-card">
          <h3>Total Users</h3>
          <p>{analytics.totalUsers.toLocaleString()}</p>
        </div>
        <div className="stat-card">
          <h3>Page Views</h3>
          <p>{analytics.pageViews.toLocaleString()}</p>
        </div>
        <div className="stat-card">
          <h3>Revenue</h3>
          <p>${analytics.revenue.toLocaleString()}</p>
        </div>
      </div>

      <div className="notifications-section">
        <h3>Notifications</h3>
        {notifications.length === 0 ? (
          <p>No new notifications</p>
        ) : (
          <ul>
            {notifications.map(notification => (
              <li key={notification.id} className={notification.read ? 'read' : 'unread'}>
                {notification.message}
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="settings-section">
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Notifications: {settings.notificationsEnabled ? 'Enabled' : 'Disabled'}</p>
      </div>
    </div>
  );
}

